(()=>{
const root=document.documentElement,reduced=matchMedia('(prefers-reduced-motion:reduce)'),video=document.querySelector('#ocean-video'),ambient=document.querySelector('#site-audio'),teaser=document.querySelector('#teaser-audio'),music=document.querySelector('.music-toggle'),theme=document.querySelector('.theme-toggle'),status=document.querySelector('.media-status');
const icons={play:'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m8 5 12 7-12 7Z"/></svg>',pause:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M8 5v14M16 5v14"/></svg>'};
// A fresh visit always opens in dark mode.
root.dataset.theme='dark';
theme.addEventListener('click',()=>{const inverted=root.dataset.theme!=='inverted';root.dataset.theme=inverted?'inverted':'dark';theme.setAttribute('aria-pressed',String(inverted));theme.setAttribute('aria-label',inverted?'Switch to dark mode':'Switch to inverted mode');});
if(/\/index\.html$/.test(location.pathname)){const clean=new URL('./',location.href);history.replaceState({},'',clean.pathname+location.search+location.hash);}
function runWater(){if(!reduced.matches)video.play().catch(()=>{});}runWater();reduced.addEventListener('change',()=>{if(reduced.matches)video.pause();else runWater();});
ambient.volume=.35;let activeButton=null,resumeAmbient=false;
const buttons=[...document.querySelectorAll('.teaser-toggle')];
function currentAudio(){return activeButton?teaser:ambient;}
function updateControls(){const playing=!currentAudio().paused;music.innerHTML=icons[playing?'pause':'play'];music.setAttribute('aria-pressed',String(playing));music.setAttribute('aria-label',playing?'Pause music':'Play music');for(const b of buttons){const on=b===activeButton&&!teaser.paused;b.innerHTML=icons[on?'pause':'play'];b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',(on?'Pause ':'Play ')+b.dataset.title);}}
async function playAudio(a){try{await a.play();updateControls();return true;}catch{status.textContent='Audio could not start. Please press play again.';updateControls();return false;}}
music.addEventListener('click',async()=>{const a=currentAudio();if(!a.paused){a.pause();resumeAmbient=false;}else await playAudio(a);updateControls();});
for(const b of buttons)b.addEventListener('click',async()=>{if(activeButton===b){if(teaser.paused)await playAudio(teaser);else teaser.pause();updateControls();return;}if(!activeButton)resumeAmbient=!ambient.paused;ambient.pause();teaser.pause();if(activeButton){activeButton.closest('li').querySelector('.track-progress span').style.width='0%';}activeButton=b;teaser.src=b.dataset.src;teaser.volume=1;await playAudio(teaser);status.textContent='Playing '+b.dataset.title+'.';updateControls();});
async function finishTeaser(){if(activeButton){activeButton.closest('li').querySelector('.track-progress span').style.width='0%';}activeButton=null;const resume=resumeAmbient;resumeAmbient=false;updateControls();if(resume)await playAudio(ambient);}
teaser.addEventListener('ended',finishTeaser);teaser.addEventListener('error',()=>{status.textContent='This preview could not load. Please try again.';finishTeaser();});
teaser.addEventListener('timeupdate',()=>{if(activeButton){const duration=Number(activeButton.dataset.duration); if(activeButton.dataset.full==='false')teaser.volume=Math.max(0,Math.min(1,(duration-teaser.currentTime)/5)); const pct=Math.min(100,100*teaser.currentTime/duration);activeButton.closest('li').querySelector('.track-progress span').style.width=pct+'%';}});
for(const a of [ambient,teaser])for(const event of ['play','pause'])a.addEventListener(event,updateControls);
const counter=document.querySelector('.countdown');function tick(){const total=Math.max(0,Math.ceil((Date.parse(counter.dataset.release)-Date.now())/1000));for(const[k,v]of Object.entries({days:Math.floor(total/86400),hours:Math.floor(total/3600)%24,minutes:Math.floor(total/60)%60,seconds:total%60}))counter.querySelector('[data-'+k+']').textContent=String(v).padStart(2,'0');if(!total)document.querySelector('[data-release-status]').textContent='The release date has arrived.';}tick();setInterval(tick,1000);
if('IntersectionObserver'in window){const reveal=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('in-view');reveal.unobserve(e.target);}},{threshold:.08});if(!reduced.matches){root.classList.add('motion-ready');document.querySelectorAll('.reveal').forEach(el=>reveal.observe(el));}const sectionObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});},{rootMargin:'-20% 0px -55% 0px'});document.querySelectorAll('main>section').forEach(s=>sectionObserver.observe(s));}
// Small, short-lived ripples belong to the water layer; the system pointer remains intact.
const canvas=document.querySelector('#ocean-ripples'),ctx=canvas.getContext('2d');let ripples=[],frame=0,last=0,lastX=-100,lastY=-100;
function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=innerWidth*dpr;canvas.height=innerHeight*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}resize();addEventListener('resize',resize);
function draw(now){ctx.clearRect(0,0,innerWidth,innerHeight);ripples=ripples.filter(r=>now-r.born<1500);for(const r of ripples){const t=(now-r.born)/1500;ctx.beginPath();ctx.ellipse(r.x,r.y,8+t*70,4+t*30,0,0,Math.PI*2);ctx.strokeStyle='rgba(188,225,224,'+((1-t)*.18)+')';ctx.lineWidth=.7;ctx.stroke();}frame=ripples.length?requestAnimationFrame(draw):0;}
addEventListener('pointermove',e=>{if(e.pointerType==='touch'||reduced.matches||!matchMedia('(pointer:fine)').matches)return;const now=performance.now();if(now-last<100||Math.hypot(e.clientX-lastX,e.clientY-lastY)<18)return;last=now;lastX=e.clientX;lastY=e.clientY;ripples.push({x:e.clientX,y:e.clientY,born:now});if(ripples.length>14)ripples.shift();if(!frame)frame=requestAnimationFrame(draw);},{passive:true});
})();

